<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$events=[];$attempts=[];
try{$pdo=business_db();security_step17_ensure($pdo);$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$stmt=$pdo->prepare("SELECT a.id,a.event_type,a.entity_type,a.entity_id,a.details_json,a.ip_address,a.created_at,u.full_name,u.email FROM audit_logs a LEFT JOIN system_users u ON u.id=a.user_id WHERE a.organization_id=? AND a.event_type LIKE 'security_%' ORDER BY a.id DESC LIMIT 250");$stmt->execute([$orgId]);$events=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT id,identifier_hash,ip_address,was_successful,failure_reason,attempted_at FROM security_login_attempts WHERE organization_id=? ORDER BY id DESC LIMIT 250");$stmt->execute([$orgId]);$attempts=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security Audit - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • Security Audit</small></span></a><div class="os-top-actions"><a class="os-btn" href="security_sessions.php">Sessions</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Security</div><nav class="os-nav"><a href="security_center.php"><i class="dot"></i>Security Center</a><a href="user_management.php"><i class="dot"></i>Users</a><a href="permission_matrix.php"><i class="dot"></i>Permissions</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a class="active" href="security_audit.php"><i class="dot"></i>Audit</a><a href="step17_audit.php"><i class="dot"></i>STEP 17 Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">SECURITY EVENT TRACE</div><h1>Authentication and access-control changes stay reviewable.</h1><p>Login identifiers are stored as one-way hashes in the attempt ledger. Passwords are never written to audit history.</p></section><?php if($error):?><div class="pp-alert bad"><?= security_step17_h($error) ?></div><?php endif;?><section class="pp-grid"><article class="os-card pp-span-6"><h2>Login Attempts</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Time</th><th>Result</th><th>Identifier Hash</th><th>IP</th><th>Reason</th></tr></thead><tbody><?php foreach($attempts as $a):?><tr><td><?= security_step17_h($a['attempted_at']) ?></td><td><span class="pp-badge <?= (int)$a['was_successful']===1?'':'warn' ?>"><?= (int)$a['was_successful']===1?'SUCCESS':'FAILED' ?></span></td><td><code><?= security_step17_h(substr((string)$a['identifier_hash'],0,14).'…') ?></code></td><td><?= security_step17_h($a['ip_address']?:'—') ?></td><td><?= security_step17_h($a['failure_reason']?:'—') ?></td></tr><?php endforeach;?><?php if(!$attempts):?><tr><td colspan="5">No login attempts recorded yet.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-6"><h2>Security Events</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Time</th><th>Event</th><th>User</th><th>Entity</th><th>IP</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?= security_step17_h($e['created_at']) ?></td><td><b><?= security_step17_h($e['event_type']) ?></b></td><td><?= security_step17_h($e['full_name']?:'System/unknown') ?><small><?= security_step17_h($e['email']?:'') ?></small></td><td><?= security_step17_h(($e['entity_type']?:'—').($e['entity_id']?' #'.$e['entity_id']:'')) ?></td><td><?= security_step17_h($e['ip_address']?:'—') ?></td></tr><?php endforeach;?><?php if(!$events):?><tr><td colspan="5">No security events recorded yet.</td></tr><?php endif;?></tbody></table></div></article></section><div class="os-footer-note"><strong>Audit scope:</strong> sign-in success/failure, logout, access denied, user/role changes, password resets/changes and session revocation remain separate from operational business facts.</div></main></div></body></html>